fn compact_constant_ad_scalar_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    let scalar = compact_constant_ad_scalar_expr(value)?;
    Some(format!("scratch.store_scalar({target_index}, {scalar});"))
}

fn compact_constant_ad_scalar_expr(value: &str) -> Option<String> {
    if let Some(args) = compact_ad_call_args(value, "constant") {
        if args.len() != 1 {
            return None;
        }
        return Some(args[0].trim().to_string());
    }

    if let Some(args) = compact_ad_call_args(value, "neg") {
        if args.len() != 1 {
            return None;
        }
        let value = compact_constant_ad_scalar_expr(args[0])?;
        return Some(format!("-({value})"));
    }

    if let Some(args) = compact_ad_call_args(value, "scale") {
        if args.len() != 2 {
            return None;
        }
        let value = compact_constant_ad_scalar_expr(args[0])?;
        return Some(format!("({value} * {})", args[1]));
    }

    if let Some(args) = compact_ad_call_args(value, "offset") {
        if args.len() != 2 {
            return None;
        }
        let value = compact_constant_ad_scalar_expr(args[0])?;
        return Some(format!("({value} + {})", args[1]));
    }

    if let Some(args) = compact_ad_call_args(value, "scaled_offset") {
        if args.len() != 3 {
            return None;
        }
        let value = compact_constant_ad_scalar_expr(args[0])?;
        return Some(format!("(({value} + {}) * {})", args[1], args[2]));
    }

    if let Some(args) = compact_ad_call_args(value, "exp") {
        if args.len() != 1 {
            return None;
        }
        let value = compact_constant_ad_scalar_expr(args[0])?;
        return Some(format!("({value}).exp()"));
    }

    if let Some(args) = compact_ad_call_args(value, "exp_scaled_input") {
        if args.len() != 2 {
            return None;
        }
        let value = compact_constant_ad_scalar_expr(args[0])?;
        return Some(format!("({value} * ({} as f64)).exp()", args[1]));
    }

    None
}

fn compact_scratch_choice_store_helper_call(target_index: usize, value: &str) -> Option<String> {
    for (name, helper, helper3) in [
        ("min", "store_min", "store_min3"),
        ("max", "store_max", "store_max3"),
    ] {
        let Some(args) = compact_ad_call_args(value, name) else {
            continue;
        };
        if args.len() != 2 {
            return None;
        }

        if let (Some(left), Some(right)) = (
            compact_scratch_ad_value_index(args[0]),
            compact_scratch_ad_value_index(args[1]),
        ) {
            return Some(format!(
                "scratch.{helper}({target_index}, {left}, {right});"
            ));
        }

        if let Some(inner_args) = compact_ad_call_args(args[0], name) {
            if inner_args.len() != 2 {
                return None;
            }
            let first = compact_scratch_ad_value_index(inner_args[0])?;
            let second = compact_scratch_ad_value_index(inner_args[1])?;
            let third = compact_scratch_ad_value_index(args[1])?;
            return Some(format!(
                "scratch.{helper3}({target_index}, {first}, {second}, {third});"
            ));
        }

        if let Some(inner_args) = compact_ad_call_args(args[1], name) {
            if inner_args.len() != 2 {
                return None;
            }
            let first = compact_scratch_ad_value_index(args[0])?;
            let second = compact_scratch_ad_value_index(inner_args[0])?;
            let third = compact_scratch_ad_value_index(inner_args[1])?;
            return Some(format!(
                "scratch.{helper3}({target_index}, {first}, {second}, {third});"
            ));
        }
    }

    None
}

fn compact_ddt_store_helper_call(target_index: usize, value: &str) -> Option<String> {
    compact_ddt_store_helper_call_scaled(target_index, value, "1.0")
}

fn compact_ddt_store_helper_call_scaled(
    target_index: usize,
    value: &str,
    output_scale: &str,
) -> Option<String> {
    let args = compact_ad_call_args(value, "ddt")?;
    if args.len() != 3 {
        return None;
    }

    let operand = args[0].trim();
    let derivative_scale = args[1].trim();
    let eval_args = compact_function_call_args(args[2], "eval_ddt")?;
    if eval_args.len() != 7 {
        return None;
    }
    let eval_operand = eval_args[6].trim().strip_suffix(".value")?.trim();
    if eval_operand != operand {
        return None;
    }

    let (input, input_scale) = compact_scaled_ad_expression(operand)
        .map(|(input, scale)| (input, scale))
        .unwrap_or((operand, "1.0".to_string()));
    let derivative_input_scale = compact_scale_product(&input_scale, output_scale);

    if let Some(source) = compact_scratch_ad_value_index(input) {
        let input_value = compact_scale_product(&format!("scratch.values[{source}]"), &input_scale);
        let eval = compact_scale_product(
            &compact_eval_ddt_call(&eval_args, &input_value),
            output_scale,
        );
        if derivative_input_scale == "1.0" {
            return Some(format!(
                "scratch.store_ddt_source({target_index}, {source}, {derivative_scale}, {eval});"
            ));
        }
        return Some(format!(
            "scratch.store_ddt_scaled_source({target_index}, {source}, {derivative_input_scale}, {derivative_scale}, {eval});"
        ));
    }

    if let Some(voltage_args) = compact_ad_call_args(input, "voltage") {
        if voltage_args.len() != 4 || voltage_args[0] != "ctx" {
            return None;
        }
        let nodes = compact_runtime_nodes_arg(voltage_args[1])?;
        let input_value = compact_scale_product(
            &compact_runtime_voltage_value(&nodes, voltage_args[2], voltage_args[3])?,
            &input_scale,
        );
        let eval = compact_scale_product(
            &compact_eval_ddt_call(&eval_args, &input_value),
            output_scale,
        );
        return Some(format!(
            "scratch.store_ddt_scaled_voltage({target_index}, {}, {}, {derivative_input_scale}, {derivative_scale}, {eval});",
            voltage_args[2], voltage_args[3]
        ));
    }

    let branch_args = compact_ad_call_args(input, "branch_current")?;
    if branch_args.len() != 3 || branch_args[0] != "ctx" {
        return None;
    }
    let branches = compact_runtime_branches_arg(branch_args[1])?;
    let input_value = compact_scale_product(
        &format!("ctx.branch_current({branches}[{}])", branch_args[2]),
        &input_scale,
    );
    let eval = compact_scale_product(
        &compact_eval_ddt_call(&eval_args, &input_value),
        output_scale,
    );
    Some(format!(
        "scratch.store_ddt_scaled_branch_current({target_index}, {}, {derivative_input_scale}, {derivative_scale}, {eval});",
        branch_args[2]
    ))
}

fn compact_eval_ddt_call(eval_args: &[&str], value: &str) -> String {
    let mut args = eval_args[..6].join(", ");
    args.push_str(", ");
    args.push_str(value);
    format!("eval_ddt({args})")
}

fn compact_runtime_voltage_value(nodes: &str, pos: &str, neg: &str) -> Option<String> {
    let pos = compact_runtime_voltage_node_value(nodes, pos)?;
    let neg = compact_runtime_voltage_node_value(nodes, neg)?;
    Some(compact_scalar_sub(&pos, &neg))
}

fn compact_runtime_voltage_node_value(nodes: &str, node: &str) -> Option<String> {
    let node = node.trim();
    if node == "None" {
        return Some("0.0".to_string());
    }
    let index = node.strip_prefix("Some(")?.strip_suffix(')')?.trim();
    index.parse::<usize>().ok()?;
    Some(format!("ctx.node_voltage({nodes}[{index}])"))
}

fn compact_runtime_nodes_arg(value: &str) -> Option<String> {
    match value.trim() {
        "nodes" | "&nodes" => Some("nodes".to_string()),
        "self.nodes" | "&self.nodes" => Some("self.nodes".to_string()),
        _ => None,
    }
}

fn compact_runtime_branches_arg(value: &str) -> Option<String> {
    match value.trim() {
        "branches" | "&branches" => Some("branches".to_string()),
        "self.branches" | "&self.branches" => Some("self.branches".to_string()),
        _ => None,
    }
}

fn compact_voltage_store_helper_call(target_index: usize, value: &str) -> Option<String> {
    if let Some(args) = compact_ad_call_args(value, "voltage") {
        return compact_voltage_store_helper_line(target_index, &args, None);
    }

    if let Some(args) = compact_ad_call_args(value, "scale") {
        if args.len() != 2 {
            return None;
        }
        let voltage_args = compact_ad_call_args(args[0], "voltage")?;
        return compact_voltage_store_helper_line(target_index, &voltage_args, Some(args[1]));
    }

    if let Some(args) = compact_ad_call_args(value, "neg") {
        if args.len() != 1 {
            return None;
        }
        let voltage_args = compact_ad_call_args(args[0], "voltage")?;
        return compact_voltage_store_helper_line(target_index, &voltage_args, Some("-1.0"));
    }

    if let Some(args) = compact_ad_call_args(value, "offset") {
        if args.len() != 2 {
            return None;
        }
        let voltage_args = compact_ad_call_args(args[0], "voltage")?;
        return compact_offset_voltage_store_helper_line(target_index, &voltage_args, args[1]);
    }

    if let Some(args) = compact_ad_call_args(value, "scaled_offset") {
        if args.len() != 3 {
            return None;
        }
        let voltage_args = compact_ad_call_args(args[0], "voltage")?;
        return compact_scaled_offset_voltage_store_helper_line(
            target_index,
            &voltage_args,
            args[1],
            args[2],
        );
    }

    if let Some(args) = compact_ad_call_args(value, "limited_exp_scaled_input") {
        if args.len() != 2 {
            return None;
        }
        let voltage_args = compact_ad_call_args(args[0], "voltage")?;
        return compact_limited_exp_scaled_voltage_store_helper_line(
            target_index,
            &voltage_args,
            args[1],
        );
    }

    if let Some(args) = compact_ad_call_args(value, "abs") {
        if args.len() != 1 {
            return None;
        }
        let voltage_args = compact_ad_call_args(args[0], "voltage")?;
        return compact_abs_voltage_store_helper_line(target_index, &voltage_args);
    }

    None
}

fn compact_voltage_store_helper_line(
    target_index: usize,
    args: &[&str],
    scale: Option<&str>,
) -> Option<String> {
    if args.len() != 4 {
        return None;
    }
    let helper = if let Some(scale) = scale {
        format!(
            "scratch.store_scaled_voltage({target_index}, {}, {}, {}, {}, {scale});",
            args[0], args[1], args[2], args[3]
        )
    } else {
        format!(
            "scratch.store_voltage({target_index}, {}, {}, {}, {});",
            args[0], args[1], args[2], args[3]
        )
    };
    Some(helper)
}

