fn compact_unary_mixed_multiply_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    let args = compact_ad_call_args(value, "mul")?;
    if args.len() != 2 {
        return None;
    }

    let left = compact_scratch_ad_value_index(args[0]);
    let right = compact_scratch_ad_value_index(args[1]);
    for (name, helper) in [
        ("exp", "store_mul_exp"),
        ("ln", "store_mul_ln"),
        ("ln_one_plus_exp", "store_mul_ln_one_plus_exp"),
        ("sqrt", "store_mul_sqrt"),
        ("limexp", "store_mul_limexp"),
        ("limited_exp", "store_mul_limited_exp"),
        ("abs", "store_mul_abs"),
        ("cos", "store_mul_cos"),
        ("tanh", "store_mul_tanh"),
    ] {
        match (left, right) {
            (None, Some(right)) => {
                let Some(unary_args) = compact_ad_call_args(args[0], name) else {
                    continue;
                };
                if unary_args.len() != 1 {
                    return None;
                }
                if let Some(value_source) = compact_scratch_ad_value_index(unary_args[0]) {
                    return Some(format!(
                        "scratch.{helper}_lhs({target_index}, {value_source}, {right});"
                    ));
                }
                let value = compact_scratch_or_non_atomic_ad_arg(unary_args[0])?;
                return Some(format!(
                    "scratch.{helper}_ad_lhs({target_index}, {value}, {right});"
                ));
            }
            (Some(left), None) => {
                let Some(unary_args) = compact_ad_call_args(args[1], name) else {
                    continue;
                };
                if unary_args.len() != 1 {
                    return None;
                }
                if let Some(value_source) = compact_scratch_ad_value_index(unary_args[0]) {
                    return Some(format!(
                        "scratch.{helper}_rhs({target_index}, {left}, {value_source});"
                    ));
                }
                let value = compact_scratch_or_non_atomic_ad_arg(unary_args[0])?;
                return Some(format!(
                    "scratch.{helper}_ad_rhs({target_index}, {left}, {value});"
                ));
            }
            _ => {}
        }
    }
    None
}

struct CompactAffineProduct<'a> {
    left: &'a str,
    right: &'a str,
    scale: String,
    offset: String,
    affine: bool,
}

fn compact_nested_mixed_multiply_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    let args = compact_ad_call_args(value, "mul")?;
    if args.len() != 2 {
        return None;
    }

    let left = compact_scratch_ad_value_index(args[0]);
    let right = compact_scratch_ad_value_index(args[1]);
    match (left, right) {
        (None, Some(right)) => {
            let product = compact_affine_product(args[0])?;
            compact_nested_multiply_lhs_helper_line(target_index, &product, right)
        }
        (Some(left), None) => {
            let product = compact_affine_product(args[1])?;
            compact_nested_multiply_rhs_helper_line(target_index, left, &product)
        }
        _ => None,
    }
}

fn compact_affine_product(value: &str) -> Option<CompactAffineProduct<'_>> {
    if let Some(args) = compact_ad_call_args(value, "mul") {
        if args.len() != 2 {
            return None;
        }
        return Some(CompactAffineProduct {
            left: args[0],
            right: args[1],
            scale: "1.0".to_string(),
            offset: "0.0".to_string(),
            affine: false,
        });
    }

    if let Some(args) = compact_ad_call_args(value, "scale") {
        if args.len() != 2 {
            return None;
        }
        let product_args = compact_ad_call_args(args[0], "mul")?;
        if product_args.len() != 2 {
            return None;
        }
        return Some(CompactAffineProduct {
            left: product_args[0],
            right: product_args[1],
            scale: args[1].to_string(),
            offset: "0.0".to_string(),
            affine: true,
        });
    }

    let args = compact_ad_call_args(value, "offset")?;
    if args.len() != 2 {
        return None;
    }
    let mut product = compact_affine_product(args[0])?;
    product.offset = compact_scalar_add(&product.offset, args[1]);
    product.affine = true;
    Some(product)
}

fn compact_scaled_affine_product<'a>(
    value: &'a str,
    scale: &str,
) -> Option<CompactAffineProduct<'a>> {
    let mut product = compact_affine_product(value)?;
    product.scale = compact_scalar_mul(&product.scale, scale);
    product.offset = compact_scalar_mul(&product.offset, scale);
    product.affine = true;
    Some(product)
}

fn compact_nested_multiply_lhs_helper_line(
    target_index: usize,
    product: &CompactAffineProduct<'_>,
    source: usize,
) -> Option<String> {
    let left = compact_scratch_ad_value_index(product.left);
    let right = compact_scratch_ad_value_index(product.right);
    if let (Some(left), Some(right)) = (left, right) {
        if product.affine {
            return Some(format!(
                "scratch.store_mul3_affine_lhs({target_index}, {left}, {right}, {}, {}, {source});",
                product.scale, product.offset
            ));
        }
        return Some(format!(
            "scratch.store_mul3_lhs({target_index}, {left}, {right}, {source});"
        ));
    }

    if !product.affine {
        if let Some((numerator, numerator_scale, denominator, denominator_scale)) =
            compact_div_scaled_inputs_scratch_args(product.left)
            && let Some(factor) = right
        {
            return Some(format!(
                "scratch.store_mul_div_scaled_inputs_product_lhs({target_index}, {numerator}, {numerator_scale}, {denominator}, {denominator_scale}, {factor}, {source});"
            ));
        }
        if let Some((numerator, numerator_scale, denominator, denominator_scale)) =
            compact_div_scaled_inputs_scratch_args(product.right)
            && let Some(factor) = left
        {
            return Some(format!(
                "scratch.store_mul_div_scaled_inputs_product_lhs({target_index}, {numerator}, {numerator_scale}, {denominator}, {denominator_scale}, {factor}, {source});"
            ));
        }
        if let Some(line) = compact_index_or_mixed_mul_ad_product_lhs_helper_line(
            target_index,
            product.left,
            product.right,
            source,
        ) {
            return Some(line);
        }
    }

    let left = compact_scratch_or_non_atomic_ad_arg(product.left)?;
    let right = compact_scratch_or_non_atomic_ad_arg(product.right)?;
    if product.affine {
        return Some(format!(
            "scratch.store_mul_ad_affine_product_lhs({target_index}, {left}, {right}, {}, {}, {source});",
            product.scale, product.offset
        ));
    }
    Some(format!(
        "scratch.store_mul_ad_product_lhs({target_index}, {left}, {right}, {source});"
    ))
}

fn compact_nested_multiply_rhs_helper_line(
    target_index: usize,
    source: usize,
    product: &CompactAffineProduct<'_>,
) -> Option<String> {
    let left = compact_scratch_ad_value_index(product.left);
    let right = compact_scratch_ad_value_index(product.right);
    if let (Some(left), Some(right)) = (left, right) {
        if product.affine {
            return Some(format!(
                "scratch.store_mul3_affine_rhs({target_index}, {source}, {left}, {right}, {}, {});",
                product.scale, product.offset
            ));
        }
        return Some(format!(
            "scratch.store_mul3_rhs({target_index}, {source}, {left}, {right});"
        ));
    }

    if !product.affine
        && let Some(line) = compact_index_or_mixed_mul_ad_product_rhs_helper_line(
            target_index,
            source,
            product.left,
            product.right,
        )
    {
        return Some(line);
    }

    let left = compact_scratch_or_non_atomic_ad_arg(product.left)?;
    let right = compact_scratch_or_non_atomic_ad_arg(product.right)?;
    if product.affine {
        return Some(format!(
            "scratch.store_mul_ad_affine_product_rhs({target_index}, {source}, {left}, {right}, {}, {});",
            product.scale, product.offset
        ));
    }
    Some(format!(
        "scratch.store_mul_ad_product_rhs({target_index}, {source}, {left}, {right});"
    ))
}

fn compact_fused_product3_store_helper_call(target_index: usize, value: &str) -> Option<String> {
    if let Some(args) = compact_ad_call_args(value, "mul3") {
        if args.len() != 3 {
            return None;
        }
        return compact_fused_product3_store_helper_line(
            target_index,
            args[0],
            args[1],
            args[2],
            "1.0",
        );
    }

    let args = compact_ad_call_args(value, "mul3_scaled_output")?;
    if args.len() != 4 {
        return None;
    }
    compact_fused_product3_store_helper_line(target_index, args[0], args[1], args[2], args[3])
}

fn compact_fused_product3_store_helper_line(
    target_index: usize,
    left: &str,
    middle: &str,
    right: &str,
    scale: &str,
) -> Option<String> {
    let scaled_output = !compact_scalar_same(scale, "1.0");
    if let Some(source) = compact_scratch_ad_value_index(right) {
        let product = CompactAffineProduct {
            left,
            right: middle,
            scale: scale.to_string(),
            offset: "0.0".to_string(),
            affine: scaled_output,
        };
        return compact_nested_multiply_lhs_helper_line(target_index, &product, source);
    }

    if let Some(source) = compact_scratch_ad_value_index(left) {
        let product = CompactAffineProduct {
            left: middle,
            right,
            scale: scale.to_string(),
            offset: "0.0".to_string(),
            affine: scaled_output,
        };
        return compact_nested_multiply_rhs_helper_line(target_index, source, &product);
    }

    if let Some(middle_source) = compact_scratch_ad_value_index(middle) {
        let left = compact_scratch_or_non_atomic_ad_arg(left)?;
        let right = compact_scratch_or_non_atomic_ad_arg(right)?;
        if scaled_output {
            return Some(format!(
                "scratch.store_mul3_ad_middle_scaled_output({target_index}, {left}, {middle_source}, {right}, {scale});"
            ));
        }
        return Some(format!(
            "scratch.store_mul3_ad_middle({target_index}, {left}, {middle_source}, {right});"
        ));
    }

    let left = compact_scratch_or_non_atomic_ad_arg(left)?;
    let middle = compact_scratch_or_non_atomic_ad_arg(middle)?;
    let right = compact_scratch_or_non_atomic_ad_arg(right)?;
    if scaled_output {
        return Some(format!(
            "scratch.store_mul3_ad_scaled_output({target_index}, {left}, {middle}, {right}, {scale});"
        ));
    }
    Some(format!(
        "scratch.store_mul3_ad({target_index}, {left}, {middle}, {right});"
    ))
}

fn compact_scaled_mixed_multiply_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    let args = compact_ad_call_args(value, "mul")?;
    if args.len() != 2 {
        return None;
    }

    let left = compact_scaled_or_negated_scratch_arg(args[0]);
    let right = compact_scaled_or_negated_scratch_arg(args[1]);
    match (left, right) {
        (Some((left, scale)), None) if compact_non_atomic_ad_value(args[1]) => {
            if let Some(line) =
                super::compact::lower_scaled_rhs_multiply(target_index, left, &scale, args[1])
            {
                return Some(line);
            }
            if let Some(line) =
                compact_mul_scaled_unary_rhs_helper_line(target_index, left, &scale, args[1])
            {
                return Some(line);
            }
            Some(format!(
                "scratch.store_mul_scaled_ad_rhs({target_index}, {left}, {scale}, {});",
                args[1]
            ))
        }
        (None, Some((right, scale))) if compact_non_atomic_ad_value(args[0]) => Some(format!(
            "scratch.store_mul_scaled_ad_lhs({target_index}, {}, {right}, {scale});",
            args[0]
        )),
        _ => None,
    }
}

fn compact_mul_scaled_unary_rhs_helper_line(
    target_index: usize,
    source: usize,
    output_scale: &str,
    value: &str,
) -> Option<String> {
    if let Some(args) = compact_ad_call_args(value, "square") {
        if args.len() != 1 {
            return None;
        }
        if let Some(sub_args) = compact_ad_call_args(args[0], "sub_from_scalar") {
            if sub_args.len() != 2 {
                return None;
            }
            if let Some(value_source) = compact_scratch_ad_value_index(sub_args[1]) {
                return Some(format!(
                    "scratch.store_mul_scaled_square_sub_from_scalar_rhs({target_index}, {source}, {output_scale}, {}, {value_source});",
                    sub_args[0]
                ));
            }
            let value = compact_scratch_or_non_atomic_ad_arg(sub_args[1])?;
            return Some(format!(
                "scratch.store_mul_scaled_square_sub_from_scalar_ad_rhs({target_index}, {source}, {output_scale}, {}, {value});",
                sub_args[0]
            ));
        }
        if let Some(value_source) = compact_scratch_ad_value_index(args[0]) {
            return Some(format!(
                "scratch.store_mul_scaled_square_rhs({target_index}, {source}, {output_scale}, {value_source});"
            ));
        }
        let value = compact_scratch_or_non_atomic_ad_arg(args[0])?;
        return Some(format!(
            "scratch.store_mul_scaled_square_ad_rhs({target_index}, {source}, {output_scale}, {value});"
        ));
    }

    if let Some(args) = compact_ad_call_args(value, "powf") {
        if args.len() != 2 {
            return None;
        }
        if let Some(value_source) = compact_scratch_ad_value_index(args[0]) {
            return Some(format!(
                "scratch.store_mul_scaled_powf_rhs({target_index}, {source}, {output_scale}, {value_source}, {});",
                args[1]
            ));
        }
        let value = compact_scratch_or_non_atomic_ad_arg(args[0])?;
        return Some(format!(
            "scratch.store_mul_scaled_powf_ad_rhs({target_index}, {source}, {output_scale}, {value}, {});",
            args[1]
        ));
    }

    if let Some(args) = compact_ad_call_args(value, "offset") {
        if args.len() != 2 {
            return None;
        }
        if let Some(value_source) = compact_scratch_ad_value_index(args[0]) {
            return Some(format!(
                "scratch.store_mul_scaled_offset_rhs({target_index}, {source}, {output_scale}, {value_source}, {});",
                args[1]
            ));
        }
        let value = compact_scratch_or_non_atomic_ad_arg(args[0])?;
        return Some(format!(
            "scratch.store_mul_scaled_offset_ad_rhs({target_index}, {source}, {output_scale}, {value}, {});",
            args[1]
        ));
    }

    for (name, helper) in [
        ("exp", "store_mul_scaled_exp"),
        ("ln", "store_mul_scaled_ln"),
        ("ln_one_plus_exp", "store_mul_scaled_ln_one_plus_exp"),
        ("sqrt", "store_mul_scaled_sqrt"),
        ("limexp", "store_mul_scaled_limexp"),
        ("limited_exp", "store_mul_scaled_limited_exp"),
        ("abs", "store_mul_scaled_abs"),
        ("cos", "store_mul_scaled_cos"),
        ("tanh", "store_mul_scaled_tanh"),
    ] {
        let Some(args) = compact_ad_call_args(value, name) else {
            continue;
        };
        if args.len() != 1 {
            return None;
        }
        if let Some(value_source) = compact_scratch_ad_value_index(args[0]) {
            return Some(format!(
                "scratch.{helper}_rhs({target_index}, {source}, {output_scale}, {value_source});"
            ));
        }
        let value = compact_scratch_or_non_atomic_ad_arg(args[0])?;
        return Some(format!(
            "scratch.{helper}_ad_rhs({target_index}, {source}, {output_scale}, {value});"
        ));
    }

    None
}

fn compact_mixed_scaled_operand_add_sub_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    for name in ["add", "sub"] {
        let Some(args) = compact_ad_call_args(value, name) else {
            continue;
        };
        if args.len() != 2 {
            return None;
        }

        let left = compact_scaled_or_negated_scratch_arg(args[0]);
        let right = compact_scaled_or_negated_scratch_arg(args[1]);
        match (left, right) {
            (Some((left, scale)), None) if compact_non_atomic_ad_value(args[1]) => {
                let helper = if name == "add" {
                    "store_add_scaled_ad_rhs"
                } else {
                    "store_sub_scaled_ad_rhs"
                };
                return Some(format!(
                    "scratch.{helper}({target_index}, {left}, {scale}, {});",
                    args[1]
                ));
            }
            (None, Some((right, scale))) if compact_non_atomic_ad_value(args[0]) => {
                let helper = if name == "add" {
                    "store_add_scaled_ad_lhs"
                } else {
                    "store_sub_scaled_ad_lhs"
                };
                return Some(format!(
                    "scratch.{helper}({target_index}, {}, {right}, {scale});",
                    args[0]
                ));
            }
            _ => return None,
        }
    }

    None
}

fn compact_scaled_or_negated_scratch_arg(value: &str) -> Option<(usize, String)> {
    if let Some(scale_args) = compact_ad_call_args(value, "scale") {
        if scale_args.len() != 2 {
            return None;
        }
        if let Some(source) = compact_scratch_ad_value_index(scale_args[0]) {
            return Some((source, scale_args[1].to_string()));
        }
        if let Some(neg_args) = compact_ad_call_args(scale_args[0], "neg") {
            if neg_args.len() != 1 {
                return None;
            }
            let source = compact_scratch_ad_value_index(neg_args[0])?;
            return Some((source, compact_scalar_negate(scale_args[1])));
        }
    }

    if let Some(neg_args) = compact_ad_call_args(value, "neg") {
        if neg_args.len() != 1 {
            return None;
        }
        let source = compact_scratch_ad_value_index(neg_args[0])?;
        return Some((source, "-1.0".to_string()));
    }

    None
}

fn compact_scaled_input_unary_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    for (name, fused_name, helper, ad_helper) in [
        (
            "sqrt",
            "sqrt_scaled_input",
            "store_sqrt_scaled_input",
            "store_sqrt_scaled_input_ad",
        ),
        (
            "exp",
            "exp_scaled_input",
            "store_exp_scaled_input",
            "store_exp_scaled_input_ad",
        ),
        (
            "limexp",
            "limexp_scaled_input",
            "store_limexp_scaled_input",
            "store_limexp_scaled_input_ad",
        ),
        (
            "limited_exp",
            "limited_exp_scaled_input",
            "store_limited_exp_scaled_input",
            "store_limited_exp_scaled_input_ad",
        ),
        (
            "abs",
            "abs_scaled_input",
            "store_abs_scaled_input",
            "store_abs_scaled_input_ad",
        ),
        (
            "ln",
            "ln_scaled_input",
            "store_ln_scaled_input",
            "store_ln_scaled_input_ad",
        ),
        (
            "ln_one_plus_exp",
            "ln_one_plus_exp_scaled_input",
            "store_ln_one_plus_exp_scaled_input",
            "store_ln_one_plus_exp_scaled_input_ad",
        ),
        (
            "sin",
            "sin_scaled_input",
            "store_sin_scaled_input",
            "store_sin_scaled_input_ad",
        ),
    ] {
        if let Some(args) = compact_ad_call_args(value, fused_name) {
            if args.len() != 2 {
                return None;
            }
            if args[1] == "-1.0" && name != "abs" {
                continue;
            }
            if let Some(source) = compact_scratch_ad_value_index(args[0]) {
                return Some(format!(
                    "scratch.{helper}({target_index}, {source}, {});",
                    args[1]
                ));
            }
            if compact_non_atomic_ad_value(args[0]) {
                return Some(format!(
                    "scratch.{ad_helper}({target_index}, {}, {});",
                    args[0], args[1]
                ));
            }
            return None;
        }

        let Some(args) = compact_ad_call_args(value, name) else {
            continue;
        };
        if args.len() != 1 {
            return None;
        }
        let inner_args = compact_ad_call_args(args[0], "scale")?;
        if inner_args.len() != 2 {
            return None;
        }
        if let Some(source) = compact_scratch_ad_value_index(inner_args[0]) {
            return Some(format!(
                "scratch.{helper}({target_index}, {source}, {});",
                inner_args[1]
            ));
        }
        if compact_non_atomic_ad_value(inner_args[0]) {
            return Some(format!(
                "scratch.{ad_helper}({target_index}, {}, {});",
                inner_args[0], inner_args[1]
            ));
        }
        return None;
    }

    None
}

fn compact_exp_mul_scaled_lhs_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    let args = compact_ad_call_args(value, "exp")?;
    if args.len() != 1 {
        return None;
    }
    let product_args = compact_ad_call_args(args[0], "mul_scaled_lhs")?;
    if product_args.len() != 3 {
        return None;
    }

    let left_index = compact_scratch_ad_value_index(product_args[0]);
    let right_index = compact_scratch_ad_value_index(product_args[2]);
    if left_index.is_none() && !compact_non_atomic_ad_value(product_args[0]) {
        return None;
    }
    if right_index.is_none() && !compact_non_atomic_ad_value(product_args[2]) {
        return None;
    }

    let helper = compact_index_or_mixed_product_store_helper_name(
        "store_exp_mul_scaled_lhs",
        &[left_index, right_index],
    )
    .unwrap_or_else(|| "store_exp_mul_scaled_lhs".to_string());
    Some(format!(
        "scratch.{helper}({target_index}, {}, {}, {});",
        compact_mixed_index_product_arg(left_index, product_args[0]),
        product_args[1],
        compact_mixed_index_product_arg(right_index, product_args[2])
    ))
}

fn compact_offset_input_unary_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    for (name, helper) in [
        ("sqrt", "store_sqrt_offset_input"),
        ("exp", "store_exp_offset_input"),
        ("ln", "store_ln_offset_input"),
    ] {
        let Some(args) = compact_ad_call_args(value, name) else {
            continue;
        };
        if args.len() != 1 {
            return None;
        }
        let inner_args = compact_ad_call_args(args[0], "offset")?;
        if inner_args.len() != 2 {
            return None;
        }
        let source = compact_scratch_ad_value_index(inner_args[0])?;
        return Some(format!(
            "scratch.{helper}({target_index}, {source}, {});",
            inner_args[1]
        ));
    }

    None
}

fn compact_negated_input_unary_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    for (name, fused_name, helper) in [
        ("sqrt", "sqrt_scaled_input", "store_sqrt_neg_input"),
        ("exp", "exp_scaled_input", "store_exp_neg_input"),
        ("limexp", "limexp_scaled_input", "store_limexp_neg_input"),
        (
            "limited_exp",
            "limited_exp_scaled_input",
            "store_limited_exp_neg_input",
        ),
        ("ln", "ln_scaled_input", "store_ln_neg_input"),
        (
            "ln_one_plus_exp",
            "ln_one_plus_exp_scaled_input",
            "store_ln_one_plus_exp_neg_input",
        ),
    ] {
        if let Some(args) = compact_ad_call_args(value, fused_name) {
            if args.len() != 2 || args[1] != "-1.0" {
                continue;
            }
            let source = compact_scratch_ad_value_index(args[0])?;
            return Some(format!("scratch.{helper}({target_index}, {source});"));
        }

        let Some(args) = compact_ad_call_args(value, name) else {
            continue;
        };
        if args.len() != 1 {
            return None;
        }
        let Some(neg_args) = compact_ad_call_args(args[0], "neg") else {
            continue;
        };
        if neg_args.len() != 1 {
            return None;
        }
        let source = compact_scratch_ad_value_index(neg_args[0])?;
        return Some(format!("scratch.{helper}({target_index}, {source});"));
    }

    None
}

fn compact_scaled_binary_operand_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    for (name, helper) in [
        ("add", "store_add_scaled_inputs"),
        ("sub", "store_sub_scaled_inputs"),
    ] {
        let Some(args) = compact_ad_call_args(value, name) else {
            continue;
        };
        if args.len() != 2 {
            return None;
        }
        let left = compact_scaled_or_direct_scratch_arg(args[0])?;
        let right = compact_scaled_or_direct_scratch_arg(args[1])?;
        if !left.2 || !right.2 {
            return None;
        }
        return Some(format!(
            "scratch.{helper}({target_index}, {}, {}, {}, {});",
            left.0, left.1, right.0, right.1
        ));
    }

    if let Some(args) = compact_ad_call_args(value, "mul") {
        if args.len() != 2 {
            return None;
        }
        let left = compact_scaled_or_direct_scratch_arg(args[0])?;
        let right = compact_scaled_or_direct_scratch_arg(args[1])?;
        if !left.2 && !right.2 {
            return None;
        }
        let scale = compact_scale_product(&left.1, &right.1);
        if left.0 == right.0 {
            return Some(format!(
                "scratch.store_scaled_square({target_index}, {}, {scale});",
                left.0
            ));
        }
        return Some(format!(
            "scratch.store_scaled_mul({target_index}, {}, {}, {scale});",
            left.0, right.0
        ));
    }

    if let Some(args) = compact_ad_call_args(value, "div") {
        if args.len() != 2 {
            return None;
        }
        let left = compact_scaled_or_direct_scratch_arg(args[0])?;
        let right = compact_scaled_or_direct_scratch_arg(args[1])?;
        if !left.2 && !right.2 {
            return None;
        }
        let scale = compact_scale_ratio(&left.1, &right.1);
        return Some(format!(
            "scratch.store_scaled_div({target_index}, {}, {}, {scale});",
            left.0, right.0
        ));
    }

    if let Some((left, left_scale, right, right_scale)) =
        compact_div_scaled_inputs_scratch_args(value)
    {
        let scale = compact_scale_ratio(&left_scale, &right_scale);
        return Some(format!(
            "scratch.store_scaled_div({target_index}, {left}, {right}, {scale});"
        ));
    }

    None
}

fn compact_div_scaled_inputs_scratch_args(value: &str) -> Option<(usize, String, usize, String)> {
    let args = compact_ad_call_args(value, "div_scaled_inputs")?;
    if args.len() != 4 {
        return None;
    }
    let left = compact_scratch_ad_value_index(args[0])?;
    let right = compact_scratch_ad_value_index(args[2])?;
    Some((left, args[1].to_string(), right, args[3].to_string()))
}

fn compact_scaled_or_direct_scratch_arg(value: &str) -> Option<(usize, String, bool)> {
    if let Some(source) = compact_scratch_ad_value_index(value) {
        return Some((source, "1.0".to_string(), false));
    }

    let args = compact_ad_call_args(value, "scale")?;
    if args.len() != 2 {
        return None;
    }
    let source = compact_scratch_ad_value_index(args[0])?;
    Some((source, args[1].to_string(), true))
}

fn compact_scale_product(left: &str, right: &str) -> String {
    if left == "1.0" {
        right.to_string()
    } else if right == "1.0" {
        left.to_string()
    } else {
        format!("(({left}) * ({right}))")
    }
}

fn compact_scale_ratio(left: &str, right: &str) -> String {
    if right == "1.0" {
        left.to_string()
    } else if left == "1.0" {
        format!("(1.0 / ({right}))")
    } else {
        format!("(({left}) * 1.0 / ({right}))")
    }
}

fn compact_scaled_sub_from_scalar_self_offset(
    scalar: &str,
    input_scale: &str,
    negated_input_scale: &str,
    combined_offset: &str,
) -> String {
    let expected_base = compact_scale_product(scalar, input_scale);
    let expected_base_alt = compact_scalar_mul(scalar, input_scale);
    if let Some((left, right)) = compact_split_top_level_add(combined_offset) {
        if compact_scalar_same_wrapped(left, &expected_base)
            || compact_scalar_same_wrapped(left, &expected_base_alt)
        {
            return compact_unwrap_outer_parens(right).to_string();
        }
        if compact_scalar_same_wrapped(right, &expected_base)
            || compact_scalar_same_wrapped(right, &expected_base_alt)
        {
            return compact_unwrap_outer_parens(left).to_string();
        }
    }

    compact_scalar_add_grouped(
        combined_offset,
        &compact_scalar_mul(scalar, negated_input_scale),
    )
}

fn compact_split_top_level_add(input: &str) -> Option<(&str, &str)> {
    let input = compact_unwrap_outer_parens(input.trim());
    let mut paren_depth = 0usize;
    let mut bracket_depth = 0usize;
    let mut brace_depth = 0usize;

    for (index, ch) in input.char_indices() {
        match ch {
            '(' => paren_depth = paren_depth.checked_add(1)?,
            ')' => paren_depth = paren_depth.checked_sub(1)?,
            '[' => bracket_depth = bracket_depth.checked_add(1)?,
            ']' => bracket_depth = bracket_depth.checked_sub(1)?,
            '{' => brace_depth = brace_depth.checked_add(1)?,
            '}' => brace_depth = brace_depth.checked_sub(1)?,
            '+' if paren_depth == 0 && bracket_depth == 0 && brace_depth == 0 => {
                return Some((input[..index].trim(), input[index + ch.len_utf8()..].trim()));
            }
            _ => {}
        }
    }

    None
}

fn compact_scalar_same_wrapped(left: &str, right: &str) -> bool {
    compact_unwrap_outer_parens(left) == compact_unwrap_outer_parens(right)
}

fn compact_scalar_negate_wrapped(value: &str) -> String {
    let value = compact_unwrap_outer_parens(value);
    if let Some(positive) = value.strip_prefix('-') {
        positive.to_string()
    } else {
        compact_scalar_negate(value)
    }
}

fn compact_unwrap_outer_parens(mut value: &str) -> &str {
    loop {
        value = value.trim();
        if !value.starts_with('(') || !value.ends_with(')') {
            return value;
        }

        let mut depth = 0usize;
        let mut wraps = true;
        for (index, ch) in value.char_indices() {
            match ch {
                '(' => {
                    depth = match depth.checked_add(1) {
                        Some(depth) => depth,
                        None => return value,
                    }
                }
                ')' => {
                    depth = match depth.checked_sub(1) {
                        Some(depth) => depth,
                        None => return value,
                    };
                    if depth == 0 && index + ch.len_utf8() < value.len() {
                        wraps = false;
                        break;
                    }
                }
                _ => {}
            }
        }

        if !wraps || depth != 0 {
            return value;
        }
        value = &value[1..value.len() - 1];
    }
}

fn compact_div_from_scalar_affine_input_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    if let Some(args) = compact_ad_call_args(value, "div_scalar_offset_denominator") {
        if args.len() != 4 {
            return None;
        }
        let scalar = args[0];
        let denominator = args[1];
        let offset = args[2];
        let scale = args[3];
        if compact_scalar_same(scale, "1.0")
            && let Some(line) =
                compact_div_from_scalar_offset_mul_sub_from_scalar_lhs_store_helper_line(
                    target_index,
                    scalar,
                    denominator,
                    offset,
                )
        {
            return Some(line);
        }
        if compact_scalar_same(scale, "1.0")
            && let Some(line) = compact_div_from_scalar_offset_mul_offset_lhs_store_helper_line(
                target_index,
                scalar,
                denominator,
                offset,
            )
        {
            return Some(line);
        }
        if compact_scalar_same(scale, "1.0")
            && let Some(line) = compact_div_from_scalar_offset_product_store_helper_line(
                target_index,
                scalar,
                denominator,
                offset,
            )
        {
            return Some(line);
        }
        if let Some(source) = compact_scratch_ad_value_index(denominator) {
            if compact_scalar_same(scale, "1.0") {
                return Some(format!(
                    "scratch.store_div_from_scalar_offset_input({target_index}, {scalar}, {source}, {offset});"
                ));
            }
            return Some(format!(
                "scratch.store_div_from_scalar_offset_scaled_input({target_index}, {scalar}, {source}, {scale}, {});",
                compact_scalar_mul(offset, scale)
            ));
        }

        let denominator = compact_scratch_or_non_atomic_ad_arg(denominator)?;
        if compact_scalar_same(scale, "1.0") {
            return Some(format!(
                "scratch.store_div_from_scalar_offset_ad({target_index}, {scalar}, {denominator}, {offset});"
            ));
        }
        return Some(format!(
            "scratch.store_div_from_scalar_scaled_ad({target_index}, {scalar}, AdValue::offset({denominator}, {offset}), {scale});"
        ));
    }

    let args = compact_ad_call_args(value, "div_from_scalar")?;
    if args.len() != 2 {
        return None;
    }
    let scalar = args[0];
    let denominator = args[1];

    if let Some(scale_offset_args) = compact_ad_call_args(denominator, "scale_offset") {
        if scale_offset_args.len() != 3 {
            return None;
        }
        if let Some(source) = compact_scratch_ad_value_index(scale_offset_args[0]) {
            return Some(format!(
                "scratch.store_div_from_scalar_offset_scaled_input({target_index}, {scalar}, {source}, {}, {});",
                scale_offset_args[1], scale_offset_args[2]
            ));
        }
    }

    if let Some(scaled_offset_args) = compact_ad_call_args(denominator, "scaled_offset") {
        if scaled_offset_args.len() != 3 {
            return None;
        }
        if let Some(source) = compact_scratch_ad_value_index(scaled_offset_args[0]) {
            let offset = compact_scale_product(scaled_offset_args[1], scaled_offset_args[2]);
            return Some(format!(
                "scratch.store_div_from_scalar_offset_scaled_input({target_index}, {scalar}, {source}, {}, {offset});",
                scaled_offset_args[2]
            ));
        }
    }

    if let Some(offset_args) = compact_ad_call_args(denominator, "offset") {
        if offset_args.len() != 2 {
            return None;
        }
        if let Some(line) = compact_div_from_scalar_offset_mul_sub_from_scalar_lhs_store_helper_line(
            target_index,
            scalar,
            offset_args[0],
            offset_args[1],
        ) {
            return Some(line);
        }
        if let Some(line) = compact_div_from_scalar_offset_mul_offset_lhs_store_helper_line(
            target_index,
            scalar,
            offset_args[0],
            offset_args[1],
        ) {
            return Some(line);
        }
        if let Some(line) = compact_div_from_scalar_offset_product_store_helper_line(
            target_index,
            scalar,
            offset_args[0],
            offset_args[1],
        ) {
            return Some(line);
        }
        if let Some(scale_args) = compact_ad_call_args(offset_args[0], "scale") {
            if scale_args.len() != 2 {
                return None;
            }
            if let Some(source) = compact_scratch_ad_value_index(scale_args[0]) {
                return Some(format!(
                    "scratch.store_div_from_scalar_offset_scaled_input({target_index}, {scalar}, {source}, {}, {});",
                    scale_args[1], offset_args[1]
                ));
            }
            let value = compact_scratch_or_non_atomic_ad_arg(scale_args[0])?;
            return Some(format!(
                "scratch.store_div_from_scalar_offset_ad({target_index}, {scalar}, AdValue::scale({value}, {}), {});",
                scale_args[1], offset_args[1]
            ));
        }
        if let Some(source) = compact_scratch_ad_value_index(offset_args[0]) {
            return Some(format!(
                "scratch.store_div_from_scalar_offset_input({target_index}, {scalar}, {source}, {});",
                offset_args[1]
            ));
        }
        let value = compact_scratch_or_non_atomic_ad_arg(offset_args[0])?;
        return Some(format!(
            "scratch.store_div_from_scalar_offset_ad({target_index}, {scalar}, {value}, {});",
            offset_args[1]
        ));
    }

    if let Some(scale_args) = compact_ad_call_args(denominator, "scale") {
        if scale_args.len() != 2 {
            return None;
        }
        if let Some(offset_args) = compact_ad_call_args(scale_args[0], "offset") {
            if offset_args.len() != 2 {
                return None;
            }
            let offset = compact_scale_product(offset_args[1], scale_args[1]);
            if let Some(source) = compact_scratch_ad_value_index(offset_args[0]) {
                return Some(format!(
                    "scratch.store_div_from_scalar_offset_scaled_input({target_index}, {scalar}, {source}, {}, {offset});",
                    scale_args[1]
                ));
            }
            let value = compact_scratch_or_non_atomic_ad_arg(offset_args[0])?;
            return Some(format!(
                "scratch.store_div_from_scalar_scaled_ad({target_index}, {scalar}, AdValue::offset({value}, {}), {});",
                offset_args[1], scale_args[1]
            ));
        }
        if let Some(source) = compact_scratch_ad_value_index(scale_args[0]) {
            return Some(format!(
                "scratch.store_div_from_scalar_scaled_input({target_index}, {scalar}, {source}, {});",
                scale_args[1]
            ));
        }
        let value = compact_scratch_or_non_atomic_ad_arg(scale_args[0])?;
        return Some(format!(
            "scratch.store_div_from_scalar_scaled_ad({target_index}, {scalar}, {value}, {});",
            scale_args[1]
        ));
    }

    for (name, helper) in [
        ("add", "store_div_from_scalar_add_ad"),
        ("sub", "store_div_from_scalar_sub_ad"),
        ("mul", "store_div_from_scalar_mul_ad"),
        ("div", "store_div_from_scalar_div_ad"),
        ("pow", "store_div_from_scalar_pow_ad"),
    ] {
        if let Some(denominator_args) = compact_ad_call_args(denominator, name) {
            if denominator_args.len() != 2 {
                return None;
            }
            let left = compact_scratch_or_non_atomic_ad_arg(denominator_args[0])?;
            let right = compact_scratch_or_non_atomic_ad_arg(denominator_args[1])?;
            return Some(format!(
                "scratch.{helper}({target_index}, {scalar}, {left}, {right});"
            ));
        }
    }

    for (name, helper) in [
        (
            "sub_from_scalar",
            "store_div_from_scalar_sub_from_scalar_ad",
        ),
        (
            "div_from_scalar",
            "store_div_from_scalar_div_from_scalar_ad",
        ),
    ] {
        if let Some(denominator_args) = compact_ad_call_args(denominator, name) {
            if denominator_args.len() != 2 {
                return None;
            }
            let value = compact_scratch_or_non_atomic_ad_arg(denominator_args[1])?;
            return Some(format!(
                "scratch.{helper}({target_index}, {scalar}, {}, {value});",
                denominator_args[0]
            ));
        }
    }

    for (name, helper) in [
        ("sqrt", "store_div_from_scalar_sqrt_ad"),
        ("square", "store_div_from_scalar_square_ad"),
        ("exp", "store_div_from_scalar_exp_ad"),
        ("sin", "store_div_from_scalar_sin_ad"),
        ("sinh", "store_div_from_scalar_sinh_ad"),
    ] {
        if let Some(denominator_args) = compact_ad_call_args(denominator, name) {
            if denominator_args.len() != 1 {
                return None;
            }
            let value = compact_scratch_or_non_atomic_ad_arg(denominator_args[0])?;
            return Some(format!(
                "scratch.{helper}({target_index}, {scalar}, {value});"
            ));
        }
    }

    if let Some(denominator_args) = compact_ad_call_args(denominator, "powf") {
        if denominator_args.len() != 2 {
            return None;
        }
        let value = compact_scratch_or_non_atomic_ad_arg(denominator_args[0])?;
        return Some(format!(
            "scratch.store_div_from_scalar_powf_ad({target_index}, {scalar}, {value}, {});",
            denominator_args[1]
        ));
    }

    None
}

fn compact_div_from_scalar_offset_product_store_helper_line(
    target_index: usize,
    scalar: &str,
    denominator: &str,
    offset: &str,
) -> Option<String> {
    if let Some(args) = compact_ad_call_args(denominator, "mul") {
        if args.len() != 2 {
            return None;
        }
        let left = compact_scratch_ad_value_index(args[0])?;
        let right = compact_scratch_ad_value_index(args[1])?;
        if left == right {
            return Some(format!(
                "scratch.store_div_from_scalar_offset_square({target_index}, {scalar}, {left}, {offset});"
            ));
        }
        return Some(format!(
            "scratch.store_div_from_scalar_offset_product({target_index}, {scalar}, {left}, {right}, {offset});"
        ));
    }

    if let Some(args) = compact_ad_call_args(denominator, "square") {
        if args.len() != 1 {
            return None;
        }
        let source = compact_scratch_ad_value_index(args[0])?;
        return Some(format!(
            "scratch.store_div_from_scalar_offset_square({target_index}, {scalar}, {source}, {offset});"
        ));
    }

    None
}

fn compact_div_from_scalar_offset_mul_sub_from_scalar_lhs_store_helper_line(
    target_index: usize,
    scalar: &str,
    denominator: &str,
    offset: &str,
) -> Option<String> {
    let args = compact_ad_call_args(denominator, "mul_sub_from_scalar_lhs")?;
    if args.len() != 3 {
        return None;
    }
    let inner_scalar = args[0];
    let value_arg = args[1];
    let right_arg = args[2];
    let value_index = compact_scratch_ad_value_index(value_arg);
    let right_index = compact_scratch_ad_value_index(right_arg);
    match (value_index, right_index) {
        (Some(value), Some(right)) => Some(format!(
            "scratch.store_div_from_scalar_offset_mul_sub_from_scalar_lhs({target_index}, {scalar}, {inner_scalar}, {value}, {right}, {offset});"
        )),
        (None, Some(right)) => {
            let value = compact_scratch_or_non_atomic_ad_arg(value_arg)?;
            Some(format!(
                "scratch.store_div_from_scalar_offset_mul_sub_from_scalar_lhs_ad_lhs({target_index}, {scalar}, {inner_scalar}, {value}, {right}, {offset});"
            ))
        }
        (Some(value), None) => {
            if let Some((rhs_input_scale, rhs_inner_offset, rhs_output_scale, rhs_offset)) =
                compact_mul_sub_from_scalar_scaled_offset_self_offset_rhs_args(
                    inner_scalar,
                    value,
                    right_arg,
                )
            {
                return Some(format!(
                    "scratch.store_div_from_scalar_offset_mul_sub_from_scalar_lhs_self_offset_rhs({target_index}, {scalar}, {inner_scalar}, {value}, {rhs_input_scale}, {rhs_inner_offset}, {rhs_output_scale}, {rhs_offset}, {offset});"
                ));
            }
            let right = compact_scratch_or_non_atomic_ad_arg(right_arg)?;
            Some(format!(
                "scratch.store_div_from_scalar_offset_mul_sub_from_scalar_lhs_ad_rhs({target_index}, {scalar}, {inner_scalar}, {value}, {right}, {offset});"
            ))
        }
        (None, None) => {
            if let Some((rhs_input_scale, rhs_inner_offset, rhs_output_scale, rhs_offset)) =
                compact_mul_sub_from_scalar_scaled_offset_self_offset_rhs_ad_args(
                    inner_scalar,
                    value_arg,
                    right_arg,
                )
            {
                if let Some((
                    value_numerator,
                    value_numerator_scale,
                    value_denominator,
                    value_denominator_scale,
                )) = compact_div_scaled_inputs_scratch_args(value_arg)
                {
                    return Some(format!(
                        "scratch.store_div_from_scalar_offset_mul_sub_from_scalar_lhs_div_scaled_inputs_self_offset_rhs({target_index}, {scalar}, {inner_scalar}, {value_numerator}, {value_numerator_scale}, {value_denominator}, {value_denominator_scale}, {rhs_input_scale}, {rhs_inner_offset}, {rhs_output_scale}, {rhs_offset}, {offset});"
                    ));
                }
                let value = compact_scratch_or_non_atomic_ad_arg(value_arg)?;
                return Some(format!(
                    "scratch.store_div_from_scalar_offset_mul_sub_from_scalar_lhs_ad_self_offset_rhs({target_index}, {scalar}, {inner_scalar}, {value}, {rhs_input_scale}, {rhs_inner_offset}, {rhs_output_scale}, {rhs_offset}, {offset});"
                ));
            }
            let value = compact_scratch_or_non_atomic_ad_arg(value_arg)?;
            let right = compact_scratch_or_non_atomic_ad_arg(right_arg)?;
            Some(format!(
                "scratch.store_div_from_scalar_offset_mul_sub_from_scalar_lhs_ad({target_index}, {scalar}, {inner_scalar}, {value}, {right}, {offset});"
            ))
        }
    }
}

fn compact_mul_sub_from_scalar_scaled_offset_self_offset_rhs_args<'a>(
    inner_scalar: &str,
    value_index: usize,
    right: &'a str,
) -> Option<(&'a str, &'a str, &'a str, &'a str)> {
    let offset_args = compact_ad_call_args(right, "offset")?;
    if offset_args.len() != 2 {
        return None;
    }

    let self_args = compact_ad_call_args(offset_args[0], "mul_sub_from_scalar_scaled_offset_self")?;
    if self_args.len() != 5 {
        return None;
    }

    if !compact_scalar_same_wrapped(inner_scalar, self_args[0])
        || compact_scratch_ad_value_index(self_args[1])? != value_index
    {
        return None;
    }

    Some((self_args[2], self_args[3], self_args[4], offset_args[1]))
}

fn compact_mul_sub_from_scalar_scaled_offset_self_offset_rhs_ad_args<'a>(
    inner_scalar: &str,
    value_arg: &str,
    right: &'a str,
) -> Option<(&'a str, &'a str, &'a str, &'a str)> {
    let offset_args = compact_ad_call_args(right, "offset")?;
    if offset_args.len() != 2 {
        return None;
    }

    let self_args = compact_ad_call_args(offset_args[0], "mul_sub_from_scalar_scaled_offset_self")?;
    if self_args.len() != 5 {
        return None;
    }

    if !compact_scalar_same_wrapped(inner_scalar, self_args[0])
        || !compact_ad_expression_same(value_arg, self_args[1])
    {
        return None;
    }

    Some((self_args[2], self_args[3], self_args[4], offset_args[1]))
}

fn compact_div_from_scalar_offset_mul_offset_lhs_store_helper_line(
    target_index: usize,
    scalar: &str,
    denominator: &str,
    output_offset: &str,
) -> Option<String> {
    let args = compact_ad_call_args(denominator, "mul_offset_lhs")?;
    if args.len() != 3 {
        return None;
    }

    let left_index = compact_scratch_ad_value_index(args[0]);
    let right_index = compact_scratch_ad_value_index(args[2]);

    if right_index.is_none()
        && let Some((helper, poly_input_scale, poly_inner_offset, poly_output_scale, right_offset)) =
            compact_scaled_softlimit_poly_offset_lhs_args(args[0], args[1], args[2])
        && let Some(helper) = compact_div_from_scalar_softlimit_poly_offset_lhs_helper_name(helper)
    {
        if let Some(left) = left_index {
            return Some(format!(
                "scratch.{helper}_mixed_ia({target_index}, {scalar}, {left}, {}, {poly_input_scale}, {poly_inner_offset}, {poly_output_scale}, {right_offset}, {output_offset});",
                args[1],
            ));
        }

        let left = compact_scratch_or_non_atomic_ad_arg(args[0])?;
        return Some(format!(
            "scratch.{helper}_ad({target_index}, {scalar}, {left}, {}, {poly_input_scale}, {poly_inner_offset}, {poly_output_scale}, {right_offset}, {output_offset});",
            args[1],
        ));
    }

    let left = compact_mixed_index_or_ad_arg(left_index, args[0])?;
    let right = compact_mixed_index_or_ad_arg(right_index, args[2])?;

    if let Some(helper) = compact_index_or_mixed_product_store_helper_name(
        "store_div_from_scalar_offset_mul_offset_lhs",
        &[left_index, right_index],
    ) {
        return Some(format!(
            "scratch.{helper}({target_index}, {scalar}, {left}, {}, {right}, {output_offset});",
            args[1],
        ));
    }

    Some(format!(
        "scratch.store_div_from_scalar_offset_mul_offset_lhs_ad({target_index}, {scalar}, {left}, {}, {right}, {output_offset});",
        args[1],
    ))
}

fn compact_div_from_scalar_softlimit_poly_offset_lhs_helper_name(
    scaled_helper: &str,
) -> Option<&'static str> {
    match scaled_helper {
        "store_scaled_softlimit_poly_offset_lhs" => {
            Some("store_div_from_scalar_softlimit_poly_offset_lhs")
        }
        "store_scaled_softlimit_poly_offset_lhs_mul_scaled" => {
            Some("store_div_from_scalar_softlimit_poly_offset_lhs_mul_scaled")
        }
        _ => None,
    }
}

fn compact_mixed_index_or_ad_arg(index: Option<usize>, expression: &str) -> Option<String> {
    index.map_or_else(
        || compact_scratch_or_non_atomic_ad_arg(expression),
        |index| Some(index.to_string()),
    )
}

fn compact_sub_from_scalar_affine_input_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    let args = compact_ad_call_args(value, "sub_from_scalar")?;
    if args.len() != 2 {
        return None;
    }
    let scalar = args[0];
    let value = args[1];

    if let Some(scale_args) = compact_ad_call_args(value, "scale") {
        if scale_args.len() != 2 {
            return None;
        }
        if let Some(source) = compact_scratch_ad_value_index(scale_args[0]) {
            return Some(format!(
                "scratch.store_sub_from_scalar_scaled_input({target_index}, {scalar}, {source}, {});",
                scale_args[1]
            ));
        }
    }

    None
}

fn compact_sqrt_general_ad_store_helper_call(target_index: usize, value: &str) -> Option<String> {
    if let Some(args) = compact_ad_call_args(value, "sqrt_scaled_input") {
        if args.len() != 2 {
            return None;
        }
        let source = compact_scratch_or_non_atomic_ad_arg(args[0])?;
        return Some(format!(
            "scratch.store_sqrt_scaled_ad({target_index}, {source}, {});",
            args[1]
        ));
    }

    let args = compact_ad_call_args(value, "sqrt")?;
    if args.len() != 1 {
        return None;
    }
    let inner = args[0];

    if let Some((numerator, numerator_scale, denominator, denominator_scale)) =
        compact_div_scaled_inputs_scratch_args(inner)
    {
        return Some(format!(
            "scratch.store_sqrt_div_scaled_inputs({target_index}, {numerator}, {numerator_scale}, {denominator}, {denominator_scale});"
        ));
    }

    for (name, helper) in [
        ("offset", "store_sqrt_offset_ad"),
        ("scale", "store_sqrt_scaled_ad"),
    ] {
        if let Some(inner_args) = compact_ad_call_args(inner, name) {
            if inner_args.len() != 2 {
                return None;
            }
            let source = compact_scratch_or_non_atomic_ad_arg(inner_args[0])?;
            return Some(format!(
                "scratch.{helper}({target_index}, {source}, {});",
                inner_args[1]
            ));
        }
    }

    if let Some(mul_scaled_args) = compact_ad_call_args(inner, "mul_scaled_lhs") {
        if mul_scaled_args.len() != 3 {
            return None;
        }
        let left = compact_scratch_ad_value_index(mul_scaled_args[0])?;
        let right = compact_scratch_ad_value_index(mul_scaled_args[2])?;
        return Some(format!(
            "scratch.store_sqrt_mul_scaled_lhs({target_index}, {left}, {}, {right});",
            mul_scaled_args[1]
        ));
    }

    for (name, helper) in [
        ("add", "store_sqrt_add_ad"),
        ("sub", "store_sqrt_sub_ad"),
        ("mul", "store_sqrt_mul_ad"),
        ("div", "store_sqrt_div_ad"),
    ] {
        if let Some(inner_args) = compact_ad_call_args(inner, name) {
            if inner_args.len() != 2 {
                return None;
            }
            let left = compact_scratch_or_non_atomic_ad_arg(inner_args[0])?;
            let right = compact_scratch_or_non_atomic_ad_arg(inner_args[1])?;
            return Some(format!(
                "scratch.{helper}({target_index}, {left}, {right});"
            ));
        }
    }

    for (name, helper) in [
        ("sub_from_scalar", "store_sqrt_sub_from_scalar_ad"),
        ("div_from_scalar", "store_sqrt_div_from_scalar_ad"),
    ] {
        if let Some(inner_args) = compact_ad_call_args(inner, name) {
            if inner_args.len() != 2 {
                return None;
            }
            let source = compact_scratch_or_non_atomic_ad_arg(inner_args[1])?;
            return Some(format!(
                "scratch.{helper}({target_index}, {}, {source});",
                inner_args[0]
            ));
        }
    }

    if let Some(inner_args) = compact_ad_call_args(inner, "abs") {
        if inner_args.len() != 1 {
            return None;
        }
        let source = compact_scratch_or_non_atomic_ad_arg(inner_args[0])?;
        return Some(format!(
            "scratch.store_sqrt_abs_ad({target_index}, {source});"
        ));
    }

    None
}

fn compact_sqrt_square_and_affine_store_helper_call(
    target_index: usize,
    value: &str,
) -> Option<String> {
    let args = compact_ad_call_args(value, "sqrt")?;
    if args.len() != 1 {
        return None;
    }
    let inner = args[0];

    if let Some(scale_offset_args) = compact_ad_call_args(inner, "scale_offset") {
        if scale_offset_args.len() != 3 {
            return None;
        }
        let source = compact_scratch_ad_value_index(scale_offset_args[0])?;
        return Some(format!(
            "scratch.store_sqrt_offset_scaled_input({target_index}, {source}, {}, {});",
            scale_offset_args[1], scale_offset_args[2]
        ));
    }

    if let Some(scaled_offset_args) = compact_ad_call_args(inner, "scaled_offset") {
        if scaled_offset_args.len() != 3 {
            return None;
        }
        let source = compact_scratch_ad_value_index(scaled_offset_args[0])?;
        let offset = compact_scale_product(scaled_offset_args[1], scaled_offset_args[2]);
        return Some(format!(
            "scratch.store_sqrt_offset_scaled_input({target_index}, {source}, {}, {offset});",
            scaled_offset_args[2]
        ));
    }

    if let Some(offset_args) = compact_ad_call_args(inner, "offset") {
        if offset_args.len() != 2 {
            return None;
        }
        if let Some(scale_args) = compact_ad_call_args(offset_args[0], "scale") {
            if scale_args.len() != 2 {
                return None;
            }
            let source = compact_scratch_ad_value_index(scale_args[0])?;
            return Some(format!(
                "scratch.store_sqrt_offset_scaled_input({target_index}, {source}, {}, {});",
                scale_args[1], offset_args[1]
            ));
        }
        if let Some(source) = compact_square_scratch_arg(offset_args[0]) {
            return Some(format!(
                "scratch.store_sqrt_square_offset({target_index}, {source}, {});",
                offset_args[1]
            ));
        }
        if let Some((source, square_offset)) = compact_offset_square_scratch_arg(offset_args[0]) {
            return Some(format!(
                "scratch.store_sqrt_offset_square_offset({target_index}, {source}, {square_offset}, {});",
                offset_args[1]
            ));
        }
    }

    if let Some(div_scaled_product_offset_denominator_args) =
        compact_ad_call_args(inner, "div_scaled_product_offset_denominator")
    {
        if div_scaled_product_offset_denominator_args.len() != 6 {
            return None;
        }
        let product_left =
            compact_scratch_ad_value_index(div_scaled_product_offset_denominator_args[0])?;
        let product_right =
            compact_scratch_ad_value_index(div_scaled_product_offset_denominator_args[1])?;
        let denominator_square =
            compact_square_scratch_arg(div_scaled_product_offset_denominator_args[3])?;
        if product_left == product_right && product_left == denominator_square {
            return Some(format!(
                "scratch.store_sqrt_div_scaled_square_offset_denominator({target_index}, {product_left}, {}, {}, {});",
                div_scaled_product_offset_denominator_args[2],
                div_scaled_product_offset_denominator_args[4],
                div_scaled_product_offset_denominator_args[5]
            ));
        }
    }

    if let Some(add_args) = compact_ad_call_args(inner, "add") {
        if add_args.len() != 2 {
            return None;
        }
        let left_square = compact_square_scratch_arg(add_args[0]);
        let right_square = compact_square_scratch_arg(add_args[1]);
        if let (Some(left), Some(right)) = (left_square, right_square) {
            return Some(format!(
                "scratch.store_sqrt_square_sum({target_index}, {left}, {right});"
            ));
        }
        if let Some(square_source) = left_square {
            let add_source = compact_scratch_ad_value_index(add_args[1])?;
            return Some(format!(
                "scratch.store_sqrt_square_add({target_index}, {square_source}, {add_source});"
            ));
        }
        if let Some(square_source) = right_square {
            let add_source = compact_scratch_ad_value_index(add_args[0])?;
            return Some(format!(
                "scratch.store_sqrt_square_add({target_index}, {square_source}, {add_source});"
            ));
        }
    }

    if let Some(add_scaled_square_product_args) =
        compact_ad_call_args(inner, "add_scaled_square_product")
    {
        if add_scaled_square_product_args.len() != 5 {
            return None;
        }
        let square_source = compact_scratch_ad_value_index(add_scaled_square_product_args[0])?;
        if let Some(cube_source) = compact_square_scratch_arg(add_scaled_square_product_args[2]) {
            let product_right = compact_scratch_ad_value_index(add_scaled_square_product_args[3])?;
            if cube_source == product_right {
                return Some(format!(
                    "scratch.store_sqrt_add_scaled_square_cube_product({target_index}, {square_source}, {}, {cube_source}, {});",
                    add_scaled_square_product_args[1], add_scaled_square_product_args[4]
                ));
            }
        }
        let product_left = compact_scratch_ad_value_index(add_scaled_square_product_args[2])?;
        let product_right = compact_scratch_ad_value_index(add_scaled_square_product_args[3])?;
        return Some(format!(
            "scratch.store_sqrt_add_scaled_square_product({target_index}, {square_source}, {}, {product_left}, {product_right}, {});",
            add_scaled_square_product_args[1], add_scaled_square_product_args[4]
        ));
    }

    if let Some(add_scaled_args) = compact_ad_call_args(inner, "add_scaled_inputs") {
        return compact_sqrt_add_sub_scaled_square_input_store_helper_line(
            target_index,
            &add_scaled_args,
            false,
        );
    }

    if let Some(sub_scaled_args) = compact_ad_call_args(inner, "sub_scaled_inputs") {
        return compact_sqrt_add_sub_scaled_square_input_store_helper_line(
            target_index,
            &sub_scaled_args,
            true,
        );
    }

    None
}

fn compact_sqrt_add_sub_scaled_square_input_store_helper_line(
    target_index: usize,
    args: &[&str],
    subtract_rhs: bool,
) -> Option<String> {
    if args.len() != 4 {
        return None;
    }

    let left_square = compact_square_scratch_arg(args[0]);
    let right_square = compact_square_scratch_arg(args[2]);

    match (left_square, right_square) {
        (Some(square_source), None) => {
            let input = compact_scratch_ad_value_index(args[2])?;
            let input_scale = if subtract_rhs {
                compact_scalar_negate(args[3])
            } else {
                args[3].to_string()
            };
            Some(format!(
                "scratch.store_sqrt_add_scaled_square_input({target_index}, {square_source}, {}, {input}, {input_scale});",
                args[1]
            ))
        }
        (None, Some(square_source)) => {
            let input = compact_scratch_ad_value_index(args[0])?;
            let square_scale = if subtract_rhs {
                compact_scalar_negate(args[3])
            } else {
                args[3].to_string()
            };
            Some(format!(
                "scratch.store_sqrt_add_scaled_square_input({target_index}, {square_source}, {square_scale}, {input}, {});",
                args[1]
            ))
        }
        _ => None,
    }
}

fn compact_square_scratch_arg(value: &str) -> Option<usize> {
    if let Some(args) = compact_ad_call_args(value, "square") {
        if args.len() != 1 {
            return None;
        }
        return compact_scratch_ad_value_index(args[0]);
    }

    if let Some(args) = compact_ad_call_args(value, "mul") {
        if args.len() != 2 {
            return None;
        }
        let left = compact_scratch_ad_value_index(args[0])?;
        let right = compact_scratch_ad_value_index(args[1])?;
        if left == right {
            return Some(left);
        }
        return None;
    }

    if let Some(args) = compact_ad_call_args(value, "mul_scaled_output") {
        if args.len() != 3 || !compact_scalar_same(args[2], "1.0") {
            return None;
        }
        let left = compact_scratch_ad_value_index(args[0])?;
        let right = compact_scratch_ad_value_index(args[1])?;
        if left == right {
            return Some(left);
        }
    }

    None
}

fn compact_any_ad_value(value: &str) -> bool {
    compact_scratch_ad_value_index(value).is_some() || compact_non_atomic_ad_value(value)
}

fn compact_square_any_ad_arg(value: &str) -> Option<&str> {
    if let Some(args) = compact_ad_call_args(value, "square") {
        if args.len() != 1 || !compact_any_ad_value(args[0]) {
            return None;
        }
        return Some(args[0]);
    }

    if let Some(args) = compact_ad_call_args(value, "mul") {
        if args.len() != 2
            || !compact_any_ad_value(args[0])
            || !compact_ad_expression_same(args[0], args[1])
        {
            return None;
        }
        return Some(args[0]);
    }

    if let Some(args) = compact_ad_call_args(value, "mul_scaled_output") {
        if args.len() != 3
            || !compact_scalar_same(args[2], "1.0")
            || !compact_any_ad_value(args[0])
            || !compact_ad_expression_same(args[0], args[1])
        {
            return None;
        }
        return Some(args[0]);
    }

    None
}

